Using Stack - O(n) Time and O(n) SpaceThe idea is to use a stack to efficiently remove consecutive duplicate words while maintaining order. As we iterate through the array, we check if the top element of the stack matches the current word. If they are the same, we pop the stack, otherwise, we push the word.
            C++

    // C++ program to delete consecutive 
// same words using Stack
#include <bits/stdc++.h>
using namespace std;

// Function to remove consecutive same 
// words using stack
int removeConsecutiveSame(vector<string>& arr) {

    stack<string> stk;

    // Traverse the array
    for (string &word : arr) {

        // If stack is not empty and top element 
        // is same as current
        if (!stk.empty() && stk.top() == word) {
            stk.pop(); 
        } else {

            // Push if no consecutive duplicate
            stk.push(word); 
        }
    }

    return stk.size();
}

// Driver code
int main() {

    vector<string> arr = {"gfg", "for", "geeks", 
                          "geeks", "for"};

    cout << removeConsecutiveSame(arr) << endl;

    return 0;
}


